Set<State> followes(State state) {
  Set<State> states = {};
  List<State> stack = [];
  stack.add(state);

  while (stack.isNotEmpty) {
    State current = stack.removeLast();
    if (!states.contains(current)) {
      states.add(current);
      if (current.label == '\u0000') {
        // Epsilon transition
        if (current.edge1 != null) {
